import{_ as d,o as t,c as o,a1 as c}from"./chunks/framework.BKrM4vFX.js";const k=JSON.parse('{"title":"kassa-mock — эмулятор облачной кассы OFD Ferma","description":"kassa-mock эмулирует облачную кассу OFD Ferma: инструкция по API, токену, продажам, возвратам, отчётам и запуску mock-сервиса.","frontmatter":{"sourcePath":"services/kassa-mock/README.md"},"headers":[{"level":1,"title":"kassa-mock — мок облачной кассы OFD Ferma (T-038)","slug":"kassa-mock-мок-облачной-кассы-ofd-ferma-t-038","link":"#kassa-mock-мок-облачной-кассы-ofd-ferma-t-038","children":[{"level":2,"title":"Контракт (по документации Ferma)","slug":"Контракт-по-документации-ferma","link":"#Контракт-по-документации-ferma","children":[{"level":3,"title":"Валидация чека (DX-слой)","slug":"Валидация-чека-dx-слой","link":"#Валидация-чека-dx-слой","children":[]}]},{"level":2,"title":"Негативные сценарии (драйвер Фазы 4)","slug":"Негативные-сценарии-драйвер-Фазы-4","link":"#Негативные-сценарии-драйвер-Фазы-4","children":[]},{"level":2,"title":"Запуск","slug":"Запуск","link":"#Запуск","children":[]},{"level":2,"title":"Подключение своего приложения к моку","slug":"Подключение-своего-приложения-к-моку","link":"#Подключение-своего-приложения-к-моку","children":[]},{"level":2,"title":"Конфиг (env)","slug":"Конфиг-env","link":"#Конфиг-env","children":[]},{"level":2,"title":"Песочницы и hosted tenancy (RFC-001, A-21)","slug":"Песочницы-и-hosted-tenancy-rfc-001-a-21","link":"#Песочницы-и-hosted-tenancy-rfc-001-a-21","children":[]},{"level":2,"title":"staging","slug":"staging","link":"#staging","children":[]},{"level":2,"title":"Границы симуляции","slug":"Границы-симуляции","link":"#Границы-симуляции","children":[]},{"level":2,"title":"Байтовые квоты состояния (PD-02)","slug":"Байтовые-квоты-состояния-pd-02","link":"#Байтовые-квоты-состояния-pd-02","children":[]}]}],"relativePath":"services/kassa-mock/README.md","filePath":"services/kassa-mock/README.md"}'),a={name:"services/kassa-mock/README.md"};function s(i,e,l,r,n,h){return t(),o("div",null,[...e[0]||(e[0]=[c(`<p>© 2026 ООО «Аксиома» ИНН:7842223709 · mock-services · Apache-2.0 SPDX-License-Identifier: Apache-2.0</p><h1 id="kassa-mock-мок-облачной-кассы-ofd-ferma-t-038" tabindex="-1">kassa-mock — мок облачной кассы OFD Ferma (T-038) <a class="header-anchor" href="#kassa-mock-мок-облачной-кассы-ofd-ferma-t-038" aria-label="Permalink to &quot;kassa-mock — мок облачной кассы OFD Ferma (T-038)&quot;">​</a></h1><p>Пара к <code>tbank-mock</code>: вместе они образуют локальный мок-стенд «банк + касса» для тестирования платёжно-фискального контура по контракту Ferma. Стенд не проксирует запросы в Ferma и не предназначен для боевых реквизитов; переключать интеграцию на production нужно отдельно, не только заменой URL.</p><p>Node.js &gt;= 18; внешние npm-зависимости не нужны. Сервер использует общий модуль <code>packages/core</code> для HTTP, персистентности, sandbox и защитных helpers.</p><h2 id="Контракт-по-документации-ferma" tabindex="-1">Контракт (по документации Ferma) <a class="header-anchor" href="#Контракт-по-документации-ferma" aria-label="Permalink to &quot;Контракт (по документации Ferma)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Метод</th><th>Поведение</th></tr></thead><tbody><tr><td><code>POST /possystem/v1/getToken</code></td><td><code>{login, pass}</code> → <code>{token}</code> (TTL 12 ч, <code>MOCK_TOKEN_TTL_MS</code>); неверные → <code>error.code=14</code>, истёкший токен → <code>error.code=11</code></td></tr><tr><td><code>POST /possystem/v1/{group}/sell</code></td><td>чек прихода («Предоплата/Аванс/Полный расчёт/Зачёт аванса») → <code>{uuid, status:&quot;wait&quot;}</code>; дубли external_id → <code>error.code=12</code>; невалидный чек → <code>error.code=4</code> + <code>field</code> + <code>hint</code></td></tr><tr><td><code>POST /possystem/v1/{group}/sell_refund</code></td><td>чек возврата прихода (опц. <code>origin_external_id</code> со сверкой остатка)</td></tr><tr><td><code>POST /possystem/v1/{group}/sell_correction</code></td><td>чек коррекции прихода (валидация <code>correction_info</code>)</td></tr><tr><td><code>POST /possystem/v1/{group}/buy</code></td><td>чек расхода (выплаты физлицам / агентские и неагентские схемы)</td></tr><tr><td><code>POST /possystem/v1/{group}/buy_refund</code></td><td>чек возврата расхода (опц. <code>origin_external_id</code> со сверкой остатка)</td></tr><tr><td><code>POST /possystem/v1/{group}/buy_correction</code></td><td>чек коррекции расхода</td></tr><tr><td><code>GET /possystem/v1/{group}/report/{uuid}</code></td><td><code>{status: wait|done|fail, ofd_status: pending|sent|rejected, payload:{ФД/ФП, ofd_receipt_url, vat_amounts, marking_verified,…}}</code></td></tr><tr><td><code>GET /possystem/v1/ofd/queue</code></td><td>очередь документов в ОФД (<code>ofdMode</code>, <code>count</code>, <code>items</code>)</td></tr><tr><td><code>POST /possystem/v1/ofd/mode</code></td><td>управление связью с ОФД (<code>{mode: &quot;online&quot;|&quot;offline&quot;|&quot;reject&quot;, flush: true}</code>)</td></tr><tr><td><code>GET /possystem/v1/stats/cashboxes/extended</code></td><td>мониторинг кассы (kktState, тариф, счётчик чеков, <code>ofdMode</code>, <code>ofdQueueCount</code>)</td></tr><tr><td><code>GET/POST/PUT /mock/time</code></td><td>виртуальные часы (<code>{&quot;advance&quot;:&quot;13h&quot;}</code>, <code>{&quot;reset&quot;:true}</code>)</td></tr><tr><td><code>GET/POST/DELETE /mock/scenarios</code></td><td>сценарное API + заголовок <code>X-Mock-Scenario: fail|hang|ofd-queue|ofd-reject|mark-fail|webhook-drop</code></td></tr><tr><td><code>GET /admin</code></td><td>консоль: последние 50 документов, фискальные данные, статус ОФД, журнал запросов; формы действий защищены подписанным CSRF-токеном и same-origin проверкой</td></tr><tr><td><code>GET /admin/journal</code></td><td>JSON-журнал последних API-запросов; креды <code>getToken</code> (<code>login</code>/<code>pass</code>), токены и реквизиты покупателя редактируются — <code>[REDACTED]</code>/маска, заголовки только из allowlist</td></tr><tr><td><code>GET /healthz</code></td><td>ok/касса недоступна + <code>ofdMode</code> и <code>ofdQueueCount</code></td></tr></tbody></table><p>Правила, история срабатываний и журнал <code>/admin/journal</code> принадлежат текущей песочнице (#52): другие песочницы их не видят и не очищают, <code>POST /mock/reset</code> действует только на целевую песочницу. Лимиты: до 200 правил на песочницу и до 8 KiB на правило (превышение — HTTP 400 с <code>code</code> <code>rule_cap_exceeded</code>/<code>rule_too_large</code>).</p><h3 id="Валидация-чека-dx-слой" tabindex="-1">Валидация чека (DX-слой) <a class="header-anchor" href="#Валидация-чека-dx-слой" aria-label="Permalink to &quot;Валидация чека (DX-слой)&quot;">​</a></h3><p>До «печати» проверяются инварианты, которые в бою проверит касса/ФНС:</p><ul><li><code>items[]</code> — непустой массив, у позиции <code>name</code>, <code>price</code>, <code>quantity</code>, <code>sum = price × quantity</code>;</li><li><code>total</code> = сумме позиций; Σ <code>payments[].sum</code> = <code>total</code>;</li><li><code>vat.type</code> — из справочника (<code>none, vat0, vat5, vat7, vat10, vat20, vat22</code>);</li><li><code>payment_method</code> — из справочника 54-ФЗ (<code>full_prepayment</code>, <code>advance</code>, <code>full_payment</code>, <code>consideration</code>, …);</li><li><code>payments[].type</code> — 1..5 (электронными/предоплата/постоплата/иная/наличные).</li></ul><p>Ошибка приходит в формате Ferma с расширением DX: <code>{&quot;error&quot;:{&quot;code&quot;:4,&quot;field&quot;:&quot;receipt.total&quot;,&quot;hint&quot;:&quot;Итог 50000 ≠ сумме позиций 100…&quot;}}</code>. Отключается <code>MOCK_VALIDATE_RECEIPTS=false</code>.</p><p>Через <code>MOCK_PROCESS_MS</code> (по умолчанию 15 с; <code>0</code> — печатать мгновенно) документ «печатается»: фиксируется время печати, присваивается уникальный номер чека за смену, генерируются ФД/ФП/фискальный признак, в лог печатается текст чека, результат POST&#39;ом уходит на <code>receipts.service.callback_url</code> (ретраи, как у Ferma, и <strong>продолжение ретраев после рестарта</strong> с <code>MOCK_STATE_FILE</code>). Чек покупателю «доставляется» страницей <code>GET /receipts/{uuid}</code> (это и есть <code>ofd_receipt_url</code>).</p><h2 id="Негативные-сценарии-драйвер-Фазы-4" tabindex="-1">Негативные сценарии (драйвер Фазы 4) <a class="header-anchor" href="#Негативные-сценарии-драйвер-Фазы-4" aria-label="Permalink to &quot;Негативные сценарии (драйвер Фазы 4)&quot;">​</a></h2><ul><li><code>external_id</code> с префиксом <strong><code>fail-</code></strong> → документ обрабатывается, статус <code>fail</code> + <code>error</code> → ядро получает callback с ошибкой, джоба ретраит;</li><li>префикс <strong><code>hang-</code></strong> → вечный <code>wait</code>, callback не отправляется (зависший чек);</li><li><code>MOCK_FERMA_DOWN=1</code> (опц. <code>MOCK_FERMA_DOWN_MS=N</code> для авто-восстановления) → все <code>/possystem/*</code> отвечают 503 «касса недоступна» — сценарий «приняли деньги, касса легла»;</li><li>неверный логин/пароль/токен → ошибки контракта (14/11);</li><li>чек с нарушенными инвариантами → ошибка 4 с указанием поля (см. выше);</li><li>кнопка «callback» в <code>/admin</code> — повторная доставка результата (проверка идемпотентности на стороне интегратора).</li></ul><blockquote><p>Префиксы <code>fail-</code>/<code>hang-</code> — удобная конвенция, если вы контролируете <code>external_id</code>. Для произвольных идентификаторов используйте заголовок <code>X-Mock-Scenario</code> или программируемые правила сценариев <code>/mock/scenarios</code>; административные кнопки работают только через форму с CSRF-токеном.</p></blockquote><h2 id="Запуск" tabindex="-1">Запуск <a class="header-anchor" href="#Запуск" aria-label="Permalink to &quot;Запуск&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> compose</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> up</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -d</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> kassa-mock</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">      # порт 3101</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># или голым node</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">MOCK_FERMA_LOGIN</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">loviitest</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> MOCK_FERMA_PASSWORD</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">mockpass123</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> node</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> services/kassa-mock/server.js</span></span></code></pre></div><p>Самотест (129 проверок: контракт Ferma и 54-ФЗ, сценарии ОФД/маркировки, управляющие токены и CSRF, песочницы, динамические ephemeral-порты, ожидание состояний вместо фиксированных sleep и рестарт callback-очереди):</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> test:kassa</span></span></code></pre></div><h2 id="Подключение-своего-приложения-к-моку" tabindex="-1">Подключение своего приложения к моку <a class="header-anchor" href="#Подключение-своего-приложения-к-моку" aria-label="Permalink to &quot;Подключение своего приложения к моку&quot;">​</a></h2><p>Приложение ходит в мок как в боевую кассу Ferma: укажите в конфигурации базовый URL мока и креды стенда (внутри docker-сети сервис доступен как <code>http://kassa-mock:3101</code>):</p><div class="language-env vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">env</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">FERMA_API_URL</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">http://kassa-mock:3101</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">   # или http://localhost:3101 с хоста</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">FERMA_LOGIN</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">loviitest</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">FERMA_PASSWORD</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">mockpass123</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">FERMA_GROUP</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">Main</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">FERMA_CALLBACK_URL</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">https://</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">ваш</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> домен</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">/api/v1/fiscal/callback</span></span></code></pre></div><p>Клиент не меняется: результаты документов приходят callback&#39;ом на <code>callback_url</code> из запроса (ретраи как у Ferma), чек покупателю доступен по ссылке <code>ofd_receipt_url</code>. Имена переменных в вашем приложении могут отличаться — важен контракт. Пошаговая цепочка curl — в <a href="./../../docs/integration/ferma-ofd">гайде «за 10 минут»</a>.</p><h2 id="Конфиг-env" tabindex="-1">Конфиг (env) <a class="header-anchor" href="#Конфиг-env" aria-label="Permalink to &quot;Конфиг (env)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Переменная</th><th>По умолчанию</th><th>Что делает</th></tr></thead><tbody><tr><td><code>MOCK_PORT</code> / <code>MOCK_HOST</code></td><td><code>3101</code> / <code>0.0.0.0</code></td><td>прослушивание</td></tr><tr><td><code>MOCK_FERMA_LOGIN</code> / <code>MOCK_FERMA_PASSWORD</code></td><td><code>loviitest</code> / <code>mockpass123</code></td><td>креды стенда</td></tr><tr><td><code>MOCK_TOKEN_TTL_MS</code></td><td>12 ч</td><td>срок жизни токена (контракт Ferma)</td></tr><tr><td><code>MOCK_PROCESS_MS</code></td><td><code>15000</code></td><td>задержка «печати»; <code>0</code> — мгновенно</td></tr><tr><td><code>MOCK_VALIDATE_RECEIPTS</code></td><td><code>true</code></td><td>проверять инварианты чека</td></tr><tr><td><code>MOCK_GROUPS</code></td><td>— (любая)</td><td>список разрешённых групп кассы, напр. <code>Main,Shop-1</code></td></tr><tr><td><code>MOCK_CALLBACK_RETRY_MS</code> / <code>MOCK_CALLBACK_MAX_ATTEMPTS</code></td><td><code>10000</code> / <code>24</code></td><td>политика доставки callback&#39;ов</td></tr><tr><td><code>MOCK_PUBLIC_BASE_URL</code></td><td><code>http://localhost:\${MOCK_KASSA_HOST_PORT:-3101}</code></td><td>база для <code>ofd_receipt_url</code> (виден покупателю!)</td></tr><tr><td><code>MOCK_AGENT_LINE</code> / <code>MOCK_AGENT_INN</code></td><td>«ТЕСТОВАЯ КАССА (МОК)» / <code>7800000000</code></td><td>шапка ленты чека (без бренда владельца стенда)</td></tr><tr><td><code>MOCK_BLOCK_PRIVATE_WEBHOOKS</code></td><td><code>false</code> (в <code>MOCK_HOSTED=1</code> — <code>true</code>)</td><td>не отправлять callback&#39;и на приватные адреса и имена, которые в них резолвятся (<code>1</code>/<code>true</code>; <code>0</code>/<code>false</code> выключает явно)</td></tr><tr><td><code>MOCK_OPERATOR_TOKEN</code></td><td>—</td><td>токен управляющей поверхности: <code>/mock/*</code>, смены ККТ, <code>/fn/state</code>, <code>/ofd/*</code> (fallback — <code>MOCK_ADMIN_TOKEN</code>)</td></tr><tr><td><code>MOCK_ADMIN_TOKEN</code></td><td>—</td><td>токен админки <code>/admin*</code>; query-токен и owner-token в <code>owned</code> tenancy сохраняются в action URL/redirect, POST дополнительно требует CSRF-токен и same-origin</td></tr><tr><td><code>MOCK_HOSTED</code></td><td><code>false</code></td><td>hosted-режим: управляющая поверхность fail-closed без токена, SSRF-политика по умолчанию</td></tr><tr><td><code>MOCK_TENANCY</code></td><td><code>owned</code> при <code>MOCK_HOSTED=1</code>, иначе <code>namespaces</code></td><td><code>owned</code>/<code>namespaces</code>/<code>off</code>; legacy <code>1</code>/<code>on</code>/<code>true</code>/<code>yes</code> → <code>owned</code>, <code>0</code>/<code>false</code>/<code>no</code> → <code>off</code>; неизвестное непустое значение пишет WARN и безопасно возвращается к default</td></tr><tr><td><code>MOCK_SANDBOX_TOKEN</code></td><td>—</td><td>owner-token default-песочницы. При <code>MOCK_HOSTED=1</code> без него <code>default</code> не обслуживается (MS-12: бизнес/form → 404, стартовый лог <code>default=closed</code>); в self-hosted <code>default</code> открыта с предупреждением при старте</td></tr><tr><td><code>MOCK_SANDBOX_TTL_MS</code></td><td>24 ч в hosted, иначе 0 (бессрочно)</td><td>TTL именованной песочницы; истёкшие удаляет sweep-воркер</td></tr><tr><td><code>MOCK_SANDBOX_MAX</code></td><td><code>100</code> в hosted, иначе <code>256</code></td><td>максимум именованных песочниц</td></tr><tr><td><code>MOCK_SANDBOX_MAX_DOCUMENTS</code></td><td><code>5000</code> в hosted, иначе <code>0</code> (без лимита)</td><td>квота документов песочницы (F-15)</td></tr><tr><td><code>MOCK_SANDBOX_HOST_SUFFIX</code></td><td>—</td><td>суффикс поддоменов песочниц, напр. <code>mock-services.dev</code>: <code>&lt;id&gt;.mock-services.dev</code></td></tr><tr><td><code>MOCK_SANDBOX_CREATE_LIMIT</code></td><td><code>20</code> в hosted, иначе <code>0</code></td><td>лимит создания песочниц на IP в час</td></tr><tr><td><code>MOCK_SANDBOX_FILE</code></td><td><code>&lt;MOCK_STATE_FILE&gt;.sandboxes.json</code></td><td>база реестра песочниц: поштучные файлы в каталоге <code>&lt;база без .json&gt;.records/</code> (owner-токены — только хэши); legacy-файл <code>&lt;база&gt;</code> переносится при старте и переименовывается в <code>.migrated</code></td></tr><tr><td><code>MOCK_SANDBOX_SWEEP_MS</code></td><td><code>60000</code></td><td>интервал воркера TTL/retention</td></tr><tr><td><code>MOCK_SANDBOX_RETENTION_MS</code></td><td><code>0</code> (выкл.)</td><td>retention диагностических записей (отправленные ОФД-записи, истёкшие токены)</td></tr><tr><td><code>MOCK_FERMA_DOWN</code> / <code>MOCK_FERMA_DOWN_MS</code></td><td><code>false</code> / <code>0</code></td><td>старт «касса недоступна» и авто-восстановление</td></tr><tr><td><code>MOCK_FN_NUMBER</code> / <code>MOCK_ECR_RN</code> / <code>MOCK_OFD_INN</code> / <code>MOCK_FNS_SITE</code></td><td>тестовые</td><td>реквизиты ФН/ККТ/ОФД и сайта ФНС в фискальном снимке</td></tr><tr><td><code>MOCK_FN_CAPACITY</code></td><td><code>250000</code></td><td>ресурс ФН: исчерпание → ошибка 63 без ожидания реального ФН</td></tr><tr><td><code>MOCK_OFD_MODE</code></td><td><code>online</code></td><td>стартовое состояние канала ОФД кассы: <code>online</code> / <code>offline</code> (очередь растёт) / <code>reject</code></td></tr><tr><td><code>MOCK_OPERATOR</code></td><td>«Кассир-мок»</td><td>имя оператора в фискальном снимке чека</td></tr><tr><td><code>MOCK_VIRTUAL_CLOCK</code></td><td>—</td><td>ISO-старт виртуальных часов стенда (TTL токена 12 ч, смена ККТ 24 ч, ресурс ФН, ретраи callback)</td></tr><tr><td><code>MOCK_STATE_FILE</code></td><td>—</td><td>файл персистентности; без него состояние в памяти</td></tr></tbody></table><h2 id="Песочницы-и-hosted-tenancy-rfc-001-a-21" tabindex="-1">Песочницы и hosted tenancy (RFC-001, A-21) <a class="header-anchor" href="#Песочницы-и-hosted-tenancy-rfc-001-a-21" aria-label="Permalink to &quot;Песочницы и hosted tenancy (RFC-001, A-21)&quot;">​</a></h2><p>Каждый запрос разрешает свою песочницу <strong>один раз</strong> и дальше видит только её состояние, креды и персистентность: параллельные A/B-запросы не смешиваются между <code>await</code> (включая токены <code>getToken</code>), а запрос без селектора всегда попадает в <code>default</code>. Селектор: <code>X-Mock-Sandbox: &lt;id&gt;</code> → <code>?sandbox=&lt;id&gt;</code> → поддомен <code>&lt;id&gt;.&lt;MOCK_SANDBOX_HOST_SUFFIX&gt;</code> (если суффикс задан).</p><table tabindex="0"><thead><tr><th>Режим</th><th>Включается</th><th>Поведение</th></tr></thead><tbody><tr><td><code>namespaces</code></td><td>дефолт self-hosted; <code>MOCK_TENANCY=namespaces</code></td><td><code>X-Mock-Sandbox</code> создаёт изолированное пространство имён для параллельных CI-воркеров; креды и управляющие токены — общие</td></tr><tr><td><code>owned</code></td><td><code>MOCK_HOSTED=1</code> по умолчанию; <code>MOCK_TENANCY=owned</code> (legacy <code>1</code>/<code>on</code>/<code>true</code>/<code>yes</code>)</td><td>у каждой песочницы свои креды Ferma и owner-token (показывается один раз); знание id без owner-token доступа не даёт (401, код 11), неизвестный id — 404 (код 10), истёкший — 410</td></tr><tr><td><code>off</code></td><td><code>MOCK_TENANCY=off</code> (legacy <code>0</code>/<code>false</code>/<code>no</code>)</td><td>одна общая песочница <code>default</code>; селектор игнорируется</td></tr></tbody></table><p>API (в <code>owned</code> — с owner-token; в <code>namespaces</code> те же маршруты управляют пространствами имён без owner-token):</p><table tabindex="0"><thead><tr><th>Запрос</th><th>Что делает</th></tr></thead><tbody><tr><td><code>POST /sandboxes</code></td><td>создать песочницу: <code>id</code>, <code>url</code>, <code>creds</code> (свой логин/пароль/группа Ferma) и <code>ownerToken</code> — показывается один раз</td></tr><tr><td><code>GET /sandboxes</code> (алиас <code>GET /mock/sandboxes</code>)</td><td>список: владельцу — своя песочница, оператору (<code>MOCK_OPERATOR_TOKEN</code>) — все</td></tr><tr><td><code>DELETE /sandboxes?sandbox=&lt;id&gt;</code></td><td>удалить песочницу вместе с состоянием (владелец или оператор)</td></tr><tr><td><code>GET /sandboxes/me</code></td><td>своя песочница: состояние, креды, TTL, расход квоты; <code>POST /sandboxes/me/reset</code>, <code>POST /sandboxes/me/reset-creds</code>, <code>DELETE /sandboxes/me</code></td></tr></tbody></table><p>Owner-token принимается в <code>Authorization: Bearer</code>, <code>X-Sandbox-Token</code> или <code>?sandbox_token=</code>. Персистентность: реестр песочниц пишется атомарно и поштучно — по файлу <code>&lt;MOCK_STATE_FILE&gt;.sandboxes.records/&lt;id&gt;.json</code> на песочницу (хэши owner-токенов + снимки состояния; мутация переписывает только свою песочницу, PD-02), а <code>default</code> всегда восстанавливается только из <code>MOCK_STATE_FILE</code> — состояние именованной песочницы не может быть выдано за <code>default</code> (F-14). Просроченные песочницы удаляет sweep-воркер; квота документов (<code>MOCK_SANDBOX_MAX_DOCUMENTS</code>, F-15) проверяется до фискализации и отвечает ошибкой 4 с подсказкой.</p><h2 id="staging" tabindex="-1">staging <a class="header-anchor" href="#staging" aria-label="Permalink to &quot;staging&quot;">​</a></h2><p>Сервис в <code>compose-core-staging-extras.yml</code> (профиль <code>mock</code>, порт 3101 на localhost). Админ-консоль: <code>curl http://localhost:3101/admin</code> с сервера.</p><h2 id="Границы-симуляции" tabindex="-1">Границы симуляции <a class="header-anchor" href="#Границы-симуляции" aria-label="Permalink to &quot;Границы симуляции&quot;">​</a></h2><ul><li>Маршруты, перечисленные выше, реализуют тестовую модель; это не облачная касса и запросы не отправляются в ОФД или ФНС. Не используйте реальные учётные записи, чеки и персональные данные.</li><li>Статусы печати <code>wait → done|fail</code> и статусы ОФД (<code>pending|sent|rejected</code>) моделируются локально; <code>ofd_receipt_url</code> указывает на страницу мока.</li><li>Контракт восстановлен по опубликованным материалам и интеграции проекта; сверяйте поведение с актуальной документацией Ferma перед изменением production-интеграции.</li></ul><h2 id="Байтовые-квоты-состояния-pd-02" tabindex="-1">Байтовые квоты состояния (PD-02) <a class="header-anchor" href="#Байтовые-квоты-состояния-pd-02" aria-label="Permalink to &quot;Байтовые квоты состояния (PD-02)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Env</th><th>Дефолт</th><th>Назначение</th></tr></thead><tbody><tr><td><code>MOCK_SANDBOX_MAX_STATE_BYTES</code></td><td>пусто: <code>8388608</code> (8 МиБ) при <code>maxDocuments &gt; 0</code>, иначе без лимита</td><td>байты JSON одной песочницы; <code>0</code> выключает</td></tr><tr><td><code>MOCK_SANDBOX_GLOBAL_MAX_STATE_BYTES</code></td><td><code>67108864</code> (64 МиБ)</td><td>сумма байт JSON всех песочниц рантайма, включая <code>default</code>; <code>0</code> выключает</td></tr></tbody></table><p>Значения задаются в целых байтах. Пусто сохраняет дефолты. Квота per-sandbox не ограничивает память контейнера; общий бюджет меньше <code>mem_limit: 128m</code>, но не равен RSS. Превышение глобального бюджета на записи или байтовых квот при импорте <code>/mock/state</code> → HTTP 400, <code>errorCode: 400</code>, <code>kind: &#39;bytes&#39;</code>, <code>code: sandbox_state_budget_exceeded</code> / <code>sandbox_state_quota_exceeded</code>, с откатом отклонённого состояния. Правила/история/журнал остаются volatile. Подробности и границы — <a href="./../../packages/core/README#байтовые-квоты-песочниц-pd-02-74">документация ядра</a>.</p>`,39)])])}const p=d(a,[["render",s]]);export{k as __pageData,p as default};
